];

interface Props {
  filings: Filing[];
  busy: boolean;
  onAsk: (question: string, filters: Filters) => void;
}

export function QuestionForm({ filings, busy, onAsk }: Props) {
  const [question, setQuestion] = useState("");
  const [ticker, setTicker] = useState("");
